{%- elif name == "bag" -%}<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="M6 7h12l1 13H5L6 7z"/><path d="M9 7a3 3 0 0 1 6 0"/></svg>
{%- elif name == "truck" -%}<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="M3 6h11v10H3zM14 10h4l3 3v3h-7"/><circle cx="7" cy="18" r="1.8"/><circle cx="17" cy="18" r="1.8"/></svg>
{%- elif name == "cal" -%}<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><rect x="3" y="5" width="18" height="16" rx="2"/><path d="M16 3v4M8 3v4M3 10h18"/></svg>
{%- elif name == "ig" -%}<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><rect x="3" y="3" width="18" height="18" rx="5"/><circle cx="12" cy="12" r="4"/><circle cx="17.5" cy="6.5" r="0.6" fill="currentColor"/></svg>
{%- elif name == "check" -%}<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.5" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="M5 12.5l4.5 4.5L19 7.5"/></svg>
{%- endif -%}
{%- endmacro -%}
{%- macro price(item) -%}{% if item.price_from %}<small>from </small>{% endif %}{{ item.price_inr | inr }}{%- endmacro -%}
{%- macro art_svg() -%}<svg class="art" viewBox="0 0 200 200" preserveAspectRatio="xMidYMid slice" aria-hidden="true" focusable="false"><use href="#lw-art"/></svg>{%- endmacro -%}
{%- macro art_panel(mono=true) -%}<div class="art-panel">{{ art_svg() }}{% if mono %}<span class="mono" aria-hidden="true">{{ monogram }}</span>{% endif %}</div>{%- endmacro -%}
{%- macro photo_panel(ph, first=false) -%}<div class="photo-panel"><img src="{{ ph.large }}" width="{{ ph.large_w }}" height="{{ ph.large_h }}" alt="{{ ph.alt }}" {% if first %}fetchpriority="high"{% else %}loading="lazy"{% endif %} decoding="async"></div>{%- endmacro -%}
{%- macro item_row(i, item) -%}
{%- set ph = photos["items"].get(item.name) -%}
<li class="item{% if ph %} has-photo{% endif %}" data-i="{{ i }}">
  {% if theme.menu == "cards" %}{% if ph %}<div class="thumb"><img src="{{ ph.small }}" width="{{ ph.small_w }}" height="{{ ph.small_h }}" alt="{{ ph.alt }}" loading="lazy" decoding="async"></div>{% else %}<div class="thumb art-tile"><svg class="art" viewBox="0 0 200 200" preserveAspectRatio="xMidYMid slice" aria-hidden="true" focusable="false" style="transform:rotate({{ (i % 4) * 90 }}deg) scale(1.7) translate({{ (i % 3) * 6 - 6 }}px,{{ (i % 5) * 4 - 8 }}px)"><use href="#lw-art"/></svg><b aria-hidden="true">{{ item.name[:1] | upper }}</b></div>{% endif %}
  {% elif ph %}<img class="item-photo" src="{{ ph.small }}" width="{{ ph.small_w }}" height="{{ ph.small_h }}" alt="{{ ph.alt }}" loading="lazy" decoding="async">{% endif %}
  <div class="item-main">
    <div class="nameline"><div class="name" id="n{{ i }}">{{ item.name }}</div><span class="leader" aria-hidden="true"></span></div>
    {% if item.description %}<div class="desc">{{ item.description }}</div>{% endif %}
  </div>
  <div class="price">{{ price(item) }}</div>
  <div class="qty">
    <label for="qty_{{ i }}">Qty</label>
    <input id="qty_{{ i }}" name="qty_{{ i }}" type="number" inputmode="numeric" min="0" max="50" step="1"
      value="{{ form.get('qty_' ~ i, 0) }}" data-price="{{ item.price_inr }}" data-name="{{ item.name }}">
    <button type="button" class="btn btn-line btn-sm add" aria-describedby="n{{ i }}">Add</button>
    <span class="step"><button type="button" class="minus" aria-label="One less {{ item.name }}">−</button><output aria-live="polite">0</output><button type="button" class="plus" aria-label="One more {{ item.name }}">+</button></span>
  </div>
</li>
{%- endmacro -%}

{%- macro section(name) -%}
{%- if name == "how" -%}
<section class="section" id="how" aria-labelledby="how-h">
  <h2 class="section-h" id="how-h">How ordering works</h2>
  {% if p.section_copy.how_ordering %}<p class="how-line">{{ p.section_copy.how_ordering }}</p>{% endif %}
  <ol class="steps">{% for title, text in steps %}<li><b>{{ title }}</b><span>{{ text }}</span></li>{% endfor %}</ol>
</section>
{%- elif name == "occasions" and categories | length > 1 -%}
<section class="section" id="occasions" aria-labelledby="occ-h">
  <h2 class="section-h" id="occ-h">Pick a gift</h2>
  <p class="section-sub">Jump to a collection.</p>
  <ul class="occasions">{% for cat in categories %}<li><a href="#cat-{{ loop.index0 }}"><b>{{ cat.name }}</b><span>{{ cat.items | length }} item{% if cat.items | length != 1 %}s{% endif %}{% if cat.from_inr %} · from {{ cat.from_inr | inr }}{% endif %}</span></a></li>{% endfor %}</ul>
</section>
{%- elif name == "about" and about_text -%}
<section class="section" id="about" aria-labelledby="about-h">
  <h2 class="section-h" id="about-h">About us</h2>
  <div class="prose">{% for para in about_text.split("\n") if para.strip() %}<p>{{ para }}</p>{% endfor %}</div>
</section>
{%- elif name == "testimonials" and p.testimonials -%}
<section class="section" id="reviews" aria-labelledby="rev-h">
  <h2 class="section-h" id="rev-h">Kind words</h2>
  <p class="section-sub">Messages from customers, shared by the seller.</p>
  <ul class="quotes">{% for t in p.testimonials %}<li><figure><blockquote>“{{ t.text }}”</blockquote><figcaption><b>{{ t.name }}</b> · shared by the seller</figcaption></figure></li>{% endfor %}</ul>
</section>
{%- elif name == "info" -%}
<section class="section" id="info" aria-labelledby="info-h">
  <h2 class="section-h" id="info-h">Visit, contact &amp; pay</h2>
  <div class="info">
    {% if p.hours or p.area %}<div class="tile">
      <h3>{% if p.hours %}Open{% else %}Where{% endif %}</h3>
      {% if p.hours %}<p>{{ p.hours }}</p>{% endif %}
      {% if p.area %}<p{% if p.hours %} class="hint" style="margin-top:6px"{% endif %}>{{ p.area }}</p>{% endif %}
    </div>{% endif %}
    {% if p.pickup_available or p.delivery_available %}<div class="tile">
      <h3>Getting your order</h3>
      {% if p.pickup_available %}<p>Pickup{% if p.area %} in {{ p.area }}{% endif %}</p>
      <p class="hint">The exact pickup address is shared on WhatsApp once your order is confirmed.</p>{% endif %}
      {% if p.delivery_available %}<p>Delivery{% if p.delivery_areas %} to {{ p.delivery_areas }}{% endif %}{% if p.delivery_fee_inr %}: {{ p.delivery_fee_inr | inr }}{% else %}: free{% endif %}</p>{% endif %}
    </div>{% endif %}
    {% if p.phone or whatsapp_url or p.instagram %}<div class="tile">
      <h3>Contact</h3>
      {% if p.phone %}<p>{{ p.phone }}</p>{% endif %}
      <div class="links">
        {% if p.phone %}<a class="btn btn-line btn-sm" href="tel:{{ p.phone | replace(' ', '') }}">{{ icon("phone") }}Call</a>{% endif %}
        {% if whatsapp_url %}<a class="btn btn-wa btn-sm" href="{{ whatsapp_url }}" target="_blank" rel="noopener">{{ icon("wa") }}WhatsApp</a>{% endif %}
        {% if p.instagram %}<a class="btn btn-line btn-sm" href="https://www.instagram.com/{{ p.instagram }}/" target="_blank" rel="noopener">{{ icon("ig") }}Instagram</a>{% endif %}
      </div>
    </div>{% endif %}
    {% if upi %}<div class="tile wide" id="pay">
      <h3>Pay by UPI</h3>
      <div class="pay">
        {{ upi_qr }}
        <div>
          <p>Scan with any UPI app, or <a href="{{ upi }}">open your UPI app</a>.</p>
          <p class="upi-name">UPI ID: <span class="upi-id">{{ p.upi_id }}</span></p>
          {% if p.upi_display_name %}<p class="upi-name">Your UPI app should show: <strong>{{ p.upi_display_name }}</strong></p>{% endif %}
          <p class="hint" style="margin-top:6px">Please confirm the amount with us before paying.</p>
        </div>
      </div>
    </div>{% endif %}
  </div>
</section>
{%- endif -%}
{%- endmacro -%}

<header class="bar">
  <div class="wrap">
    <div class="pill">
    <a class="brand" href="{{ base }}/"><span class="mono" aria-hidden="true">{{ monogram }}</span><span>{{ p.name }}</span></a>
    {% if page == "home" %}
    <nav class="links" aria-label="Sections"><a href="#menu">Menu</a>{% if "how" in theme.before or "how" in theme.after %}<a href="#how">How it works</a>{% endif %}{% if about_text %}<a href="#about">About</a>{% endif %}<a href="#info">Contact</a></nav>
    <a class="btn btn-primary btn-sm" href="#order">Order</a>
    {% else %}<a class="btn btn-line btn-sm" href="{{ base }}/">Back to the shop</a>{% endif %}
    </div>
  </div>
</header>

{% if page == "home" %}
<main class="wrap" id="main">
  <section class="hero hero-{{ theme.hero }}" id="top">
    <div class="hero-text">
      {% if eyebrow %}<p class="eyebrow">{{ eyebrow }}</p>{% endif %}
      <h1>{{ headline }}</h1>
      {% if lede %}<p class="lede">{{ lede }}</p>{% endif %}
      {% if show_area or p.hours %}<ul class="meta">
        {% if show_area %}<li>{{ icon("pin") }}{{ p.area }}</li>{% endif %}
        {% if p.hours %}<li>{{ icon("clock") }}{{ p.hours }}</li>{% endif %}
      </ul>{% endif %}
      {% if badges %}<ul class="badges" aria-label="About ordering">{% for b in badges %}<li>{{ b }}</li>{% endfor %}</ul>{% endif %}
      <div class="cta">
        <a class="btn btn-primary" href="#menu">See menu &amp; order</a>
        {% if whatsapp_url %}<a class="btn btn-wa" href="{{ whatsapp_url }}" target="_blank" rel="noopener">{{ icon("wa") }}WhatsApp</a>{% endif %}
        {% if p.phone %}<a class="btn btn-line" href="tel:{{ p.phone | replace(' ', '') }}">{{ icon("phone") }}Call</a>{% endif %}
      </div>
    </div>
    <div class="hero-art">
      {%- if theme.hero == "centered" -%}
        {%- for n in range(3) -%}{% if hero_photos | length > n %}{{ photo_panel(hero_photos[n], n == 0) }}{% else %}{{ art_panel(n == 1) }}{% endif %}{%- endfor -%}
      {%- else -%}
        {%- if hero_photos -%}{{ photo_panel(hero_photos[0], true) }}{%- else -%}{{ art_panel() }}{%- endif -%}
        {%- if theme.hero == "ledger" and min_price is not none -%}<div class="price-card"><small>Prices start at</small><b>{{ min_price | inr }}</b></div>{%- endif -%}
      {%- endif -%}
    </div>
  </section>

  {% if rest_photos %}
  <ul class="gallery n{{ rest_photos | length }}" aria-label="Photos">{% for ph in rest_photos %}
    <li><img src="{{ ph.small }}" srcset="{{ ph.small }} {{ ph.small_w }}w, {{ ph.large }} {{ ph.large_w }}w"
      sizes="(min-width: 900px) 33vw, 80vw" width="{{ ph.large_w }}" height="{{ ph.large_h }}" alt="{{ ph.alt }}"
      loading="lazy" decoding="async"></li>{% endfor %}
  </ul>
  {% endif %}

  {% for name in theme.before %}{{ section(name) }}{% endfor %}

  <form class="layout" method="post" action="{{ base }}/order" id="order-form">
    <div>
      <section class="section" id="menu" aria-labelledby="menu-h" style="padding-top:{{ '44px' if not theme.before else '40px' }}">
        <h2 class="section-h" id="menu-h">{{ 'Price list' if theme.menu == 'pricelist' else 'Menu' }}</h2>
        <p class="section-sub">Prices in rupees. Tap Add to build your order.</p>
        {% if categories | length > 1 %}
        <ul class="chips" aria-label="Jump to">{% for cat in categories %}<li><a class="chip" href="#cat-{{ loop.index0 }}">{{ cat.name }}</a></li>{% endfor %}</ul>
        {% endif %}
        {% if p.products | length >= 20 %}
        <div class="find" hidden id="find"><label class="hint" for="find-input">Find an item</label>
          <input id="find-input" type="search" placeholder="Type to search…" autocomplete="off">
          <p class="find-none" id="find-none" hidden>Nothing matches. Try another word.</p></div>
        {% endif %}
        {% for cat in categories %}
        <div class="cat c{{ loop.index0 % 6 }}{% if cat.is_plan %} plan{% endif %}" id="cat-{{ loop.index0 }}">
          {% if categories | length > 1 or cat.name | lower != "menu" %}<h3 class="cat-h">{{ cat.name }} <span class="count">{{ cat.items | length }}</span></h3>{% endif %}
          <ul class="items{% if cat.items | length >= 12 %} dense{% endif %}">{% for i, item in cat.items %}{{ item_row(i, item) }}{% endfor %}</ul>
        </div>
        {% endfor %}
        {% if extras %}
        <div class="cat c{{ categories | length % 6 }}" id="extras">
          <h3 class="cat-h">Extras <span class="count">{{ extras | length }}</span></h3>
          <p class="extras-note">Add these on top of an item.</p>
          <ul class="items">{% for i, item in extras %}{{ item_row(i, item) }}{% endfor %}</ul>
        </div>
        {% endif %}
      </section>
      {% for name in theme.after %}{{ section(name) }}{% endfor %}
    </div>

    <aside class="panel" id="order" aria-labelledby="order-h">
      <h2 id="order-h">Your order</h2>
      <p class="hint" style="margin:0">Nothing is charged here. We'll contact you to confirm the order and payment.</p>
      {% if form_error %}<p class="error" role="alert">{{ form_error }}</p>{% endif %}
      <ul class="basket" id="basket" aria-live="polite"><li class="empty">Add items from the menu{% if not categories %} below{% endif %}.</li></ul>
      <div class="total" id="total-row" hidden><span>Estimated total</span><span id="total"></span></div>
      {% if p.min_notice_days or p.pickup_available or p.delivery_available %}
      <ul class="facts-sm">
        {% if p.min_notice_days %}<li>{{ icon("cal") }}<span>Please order at least {{ p.min_notice_days }} day{% if p.min_notice_days != 1 %}s{% endif %} ahead.</span></li>{% endif %}
        {% if p.pickup_available %}<li>{{ icon("bag") }}<span>Pickup{% if p.area %} from {{ p.area }}{% endif %}.</span></li>{% endif %}
        {% if p.delivery_available %}<li>{{ icon("truck") }}<span>Delivery {% if p.delivery_fee_inr %}{{ p.delivery_fee_inr | inr }}, added by the shop{% else %}is free{% endif %}.</span></li>{% endif %}
      </ul>
      {% endif %}
      {% if p.allow_item_message %}
      <div class="field">
        <label for="item_message">Message on the item <span class="hint">(optional)</span></label>
        <input id="item_message" name="item_message" maxlength="200" placeholder="e.g. Happy Birthday Riya" value="{{ form.get('item_message', '') }}">
      </div>
      {% endif %}
      <div class="field">
        <label for="note">Anything else? <span class="hint">(optional)</span></label>
        <textarea id="note" name="note" rows="2" maxlength="1000" placeholder="Date you need it, size, colour…">{{ form.get('note', '') }}</textarea>
      </div>
      <div class="field">
        <label for="customer_name">Your name</label>
        <input id="customer_name" name="customer_name" required maxlength="80" autocomplete="name" value="{{ form.get('customer_name', '') }}">
      </div>
      <div class="field">
        <label for="customer_phone">Your phone number</label>
        <input id="customer_phone" name="customer_phone" required inputmode="tel" maxlength="20" autocomplete="tel" placeholder="98765 43210" value="{{ form.get('customer_phone', '') }}">
      </div>
      <div class="hp" aria-hidden="true"><label for="website">Leave empty</label><input id="website" name="website" tabindex="-1" autocomplete="off"></div>
      <input type="hidden" name="order_token" value="{{ order_token }}">
      <p class="hint">We use these details only to handle your order. <a href="{{ base }}/privacy">Privacy</a></p>
      {% if preview %}<p class="hint" role="note">This is a preview. Customers can order once your shop is live.</p>
      <p class="error" id="preview-off" role="status" hidden>Preview: orders are turned off until your shop is live.</p>{% endif %}
      {% if demo %}<p class="hint" role="note">This is a demo shop: sending this form places no order.</p>{% endif %}
      <button class="btn btn-primary btn-block" type="submit">Send order</button>
    </aside>
  </form>
</main>
<div class="bar-order" id="bar-order"><a href="#order"><span id="bar-count">0 items</span><span><span id="bar-total"></span> · Review →</span></a></div>

{% elif page == "thanks" %}
<main class="wrap narrow" id="main">
  <div class="plain-hero">
    <span class="done-mark">{{ icon("check") }}</span>
    <div>
      {% if demo %}<h1>This is a demo</h1>
      <p class="lede" role="status">This is a demo shop, so no order was placed and nobody was contacted. On a real shop, the order would reach the seller's inbox and you would get an order reference here.</p>
      {% else %}<h1>Thank you{% if order %}, {{ order.customer_name }}{% endif %}!</h1>
      <p class="lede">{{ p.name }} has your order and will contact you soon to confirm it.</p>{% endif %}
      {% if order and order.ref %}<p class="hint" style="margin-top:12px">Your order reference: <strong>{{ order.ref }}</strong></p>{% endif %}
    </div>
  </div>
  {% if order %}
  <section class="panel" style="position:static">
    <h2>Your order</h2>
    <ul class="basket">
      {% for it in order["items"] %}<li><span>{{ it.qty }} × {{ it.name }}</span><span>{{ (it.qty * it.price_inr) | inr }}</span></li>{% endfor %}
    </ul>
    {% if order["items"] %}<div class="total"><span>Estimated total</span><span>{{ order.total_inr | inr }}</span></div>{% endif %}
    {% if order.note %}<p class="hint">Your note: {{ order.note }}</p>{% endif %}
    <p class="hint">The final amount{% if p.delivery_available %} (for example delivery){% endif %} is confirmed by the shop.</p>
    <div class="cta">{% if order_whatsapp_url %}<a class="btn btn-wa" href="{{ order_whatsapp_url }}" target="_blank" rel="noopener">{{ icon("wa") }}Send this order to the shop</a>{% elif whatsapp_url %}<a class="btn btn-wa" href="{{ whatsapp_url }}" target="_blank" rel="noopener">{{ icon("wa") }}Message on WhatsApp</a>{% endif %}<a class="btn btn-line" href="{{ base }}/">Back to the shop</a></div>
  </section>
  {% endif %}
  <div style="height:40px"></div>
</main>

{% elif page == "privacy" %}
<main class="wrap narrow" id="main">
  <div class="plain-hero"><h1>Privacy</h1><p class="lede">How {{ p.name }} uses your details.</p></div>
  <section class="prose" style="padding-bottom:40px">
    <p><strong>What we collect.</strong> When you place an order on this site we collect your name, your phone number, what you ordered and any note you add. We don't use cookies for tracking and we don't run ads.</p>
    <p><strong>Why.</strong> Only to prepare your order and contact you about it (to confirm timing, delivery and payment).</p>
    <p><strong>Who sees it.</strong> Your order is sent by email to {{ p.name }}. It is stored securely by the service that runs this website, LaunchWitness, so the order isn't lost. We never sell or share your details for marketing.</p>
    <p><strong>Payments.</strong> This site does not take payments. If you pay by UPI, the payment happens in your own UPI app.</p>
    <p><strong>How long.</strong> Only as long as needed to handle your order and keep the shop's records.</p>
    <p><strong>Your choice.</strong> To see, correct or delete your details, contact us{% if p.phone %} on {{ p.phone }}{% endif %}{% if whatsapp_url %} or <a href="{{ whatsapp_url }}" target="_blank" rel="noopener">on WhatsApp</a>{% endif %}.</p>
  </section>
</main>
{% endif %}

<footer>
  <div class="wrap">
    <span>© {{ p.name }}{% if p.area %} · {{ p.area }}{% endif %}{% if p.fssai_number %} · FSSAI licence no. {{ p.fssai_number }}{% endif %}</span>
    <span><a href="{{ base }}/privacy">Privacy</a>{% if not preview and not demo %} · <a href="/report-shop" rel="nofollow">Report this shop</a>{% endif %} · Site by LaunchWitness</span>
  </div>
</footer>
{% if page == "home" %}
<script>
/* Basket: enhances the plain quantity boxes (the form works without this). Totals here are for display;
   the server works out the real total from the menu. */
(function () {
  document.documentElement.classList.add("js");
  var form = document.getElementById("order-form");
  if (!form) return;
  var inr = function (n) {
    var s = String(Math.round(n)), head = s.slice(0, -3), tail = s.slice(-3);
    return "₹" + (head ? head.replace(/\B(?=(\d\d)+(?!\d))/g, ",") + "," + tail : tail);
  };
  var rows = Array.prototype.slice.call(form.querySelectorAll(".item"));
  var basket = document.getElementById("basket"), totalRow = document.getElementById("total-row");
  var bar = document.getElementById("bar-order");
  function val(input) { var n = parseInt(input.value, 10); return isNaN(n) || n < 0 ? 0 : Math.min(n, 50); }
  function refresh() {
    var count = 0, total = 0, lines = [];
    rows.forEach(function (row) {
      var input = row.querySelector("input"), n = val(input);
      row.classList.toggle("chosen", n > 0);
      row.querySelector("output").textContent = n;
      if (n > 0) {
        count += n; total += n * Number(input.dataset.price);
        var li = document.createElement("li"), a = document.createElement("span"), b = document.createElement("span");
        a.textContent = n + " × " + input.dataset.name; b.textContent = inr(n * Number(input.dataset.price));
        li.appendChild(a); li.appendChild(b); lines.push(li);
      }
    });
    basket.innerHTML = "";
    if (lines.length) { lines.forEach(function (li) { basket.appendChild(li); }); }
    else { var e = document.createElement("li"); e.className = "empty"; e.textContent = "Add items from the menu."; basket.appendChild(e); }
    totalRow.hidden = !count;
    document.getElementById("total").textContent = inr(total);
    document.getElementById("bar-count").textContent = count + (count === 1 ? " item" : " items");
    document.getElementById("bar-total").textContent = inr(total);
    bar.classList.toggle("show", count > 0);
    document.body.classList.toggle("has-bar", count > 0);
  }
  rows.forEach(function (row) {
    var input = row.querySelector("input");
    var set = function (n) { input.value = Math.max(0, Math.min(50, n)); refresh(); };
    row.querySelector(".add").addEventListener("click", function () { set(1); row.querySelector(".plus").focus(); });
    row.querySelector(".plus").addEventListener("click", function () { set(val(input) + 1); });
    row.querySelector(".minus").addEventListener("click", function () {
      set(val(input) - 1); if (!val(input)) row.querySelector(".add").focus();
    });
  });
  refresh();
  var find = document.getElementById("find");
  if (find) {
    find.hidden = false;
    var box = document.getElementById("find-input"), none = document.getElementById("find-none");
    box.addEventListener("input", function () {
      var q = box.value.trim().toLowerCase(), shown = 0;
      rows.forEach(function (row) {
        var hit = !q || row.textContent.toLowerCase().indexOf(q) !== -1;
        row.hidden = !hit; if (hit) shown++;
      });
      Array.prototype.forEach.call(form.querySelectorAll(".cat"), function (cat) {
        cat.hidden = !cat.querySelector(".item:not([hidden])");
      });
      none.hidden = shown > 0;
    });
  }
})();
</script>
